class Solution:
    def uniquePaths(self, m, n):

        def dfs(r, c):
            if r == m - 1 and c == n - 1:
                return 1

            if r >= m or c >= n:
                return 0

            return (
                dfs(r + 1, c)
                +
                dfs(r, c + 1)
            )

        return dfs(0, 0)

