class Solution:
    def isInterleave(self, s1, s2, s3):

        if len(s1) + len(s2) != len(s3):
            return False

        m = len(s1)
        n = len(s2)

        dp = [
            [False] * (n + 1)
            for _ in range(m + 1)
        ]

        dp[0][0] = True

        for i in range(m + 1):
            for j in range(n + 1):

                if i == 0 and j == 0:
                    continue

                k = i + j - 1

                if i > 0 and dp[i - 1][j]:
                    if s1[i - 1] == s3[k]:
